INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Datenfluss immer aus einer Datei kommen muss?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Netzwerk oder Tastatur"}, {"text": "Ja", "correct": false, "because": "Mehrere Quellen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutze ich in Java, um Zeichen aus einer Quelle zu lesen?', 3, '[{"text": "BufferedReader", "correct": true, "because": "Effizient für Text"}, {"text": "PrintWriter", "correct": false, "because": "Für Ausgabe"}, {"text": "ArrayList", "correct": false, "because": "Datenstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Quellen kann ein Programm zum Lesen verwenden?', 5, '[{"text": "Dateien", "correct": true, "because": "Häufige Quelle"}, {"text": "Netzwerk", "correct": true, "because": "Datenströme"}, {"text": "Tastatureingaben", "correct": true, "because": "Nutzerinteraktion"}, {"text": "Bildschirmfarben", "correct": false, "because": "Keine Datenquelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Datenfluss liest byteweise. b) Er kann auch zeichenweise lesen.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Abhängig vom Typ"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Daten aus einer Quelle lese?', 4, '[{"text": "Pufferung", "correct": false, "because": "Verbessert Effizienz"}, {"text": "Fehlerbehandlung", "correct": false, "because": "Schützt Programm"}, {"text": "Bildschirmdesign", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Datenfluss immer synchron ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann asynchron sein"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Objekt wähle ich in Python, um eine Datei zeilenweise zu lesen?', 3, '[{"text": "open()", "correct": true, "because": "Öffnet Dateistrom"}, {"text": "write()", "correct": false, "because": "Für Ausgabe"}, {"text": "print()", "correct": false, "because": "Nur Anzeige"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein gepufferter Datenfluss?', 5, '[{"text": "Effizienz", "correct": true, "because": "Reduziert Zugriffe"}, {"text": "Geringere Latenz", "correct": true, "because": "Schnellerer Lesevorgang"}, {"text": "Kleinere Dateien", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) ein Datenfluss blockierend sein kann und b) er immer Netzwerkdaten liest. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einen Datenfluss zu verarbeiten?', 4, '[{"text": "Quelldefinition", "correct": false, "because": "Gibt Datenherkunft"}, {"text": "Leseoperation", "correct": false, "because": "Extrahiert Daten"}, {"text": "Grafikdesign", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Liest ein Datenfluss immer nur Text?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Binärdaten"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken nutze ich, um Fehler beim Lesen zu behandeln?', 4, '[{"text": "Try-Catch", "correct": true, "because": "Fängt Ausnahmen"}, {"text": "IOException", "correct": true, "because": "Spezifische Fehler"}, {"text": "Ignorieren", "correct": false, "because": "Riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Datenfluss nur lokale Dateien liest. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Netzwerk möglich"}, {"text": "Ja", "correct": false, "because": "Vielseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Datenfluss?', 3, '[{"text": "Daten einlesen", "correct": true, "because": "Primäre Funktion"}, {"text": "Daten anzeigen", "correct": false, "because": "Sekundär"}, {"text": "Design verbessern", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Datenfluss kann blockieren. b) Er ist immer asynchron.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Pufferung beim Lesen?', 4, '[{"text": "Leistungssteigerung", "correct": true, "because": "Reduziert Zugriffe"}, {"text": "Datenverlust", "correct": false, "because": "Nicht Zweck"}, {"text": "Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Datenfluss geschlossen werden muss?', 2, '[{"text": "Ja", "correct": true, "because": "Ressourcen freigeben"}, {"text": "Nein", "correct": false, "because": "Best Practice"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen einen Datenfluss nützlich?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Verschiedene Quellen"}, {"text": "Effizienz", "correct": true, "because": "Pufferung hilft"}, {"text": "Hohe Latenz", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Liest ein Datenfluss immer sequenziell?', 3, '[{"text": "Ja", "correct": true, "because": "Typisch für Streams"}, {"text": "Nein", "correct": false, "because": "Meist sequenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Datenfluss?', 4, '[{"text": "Logdatei einlesen", "correct": true, "because": "Typische Anwendung"}, {"text": "Grafik rendern", "correct": false, "because": "Anderer Zweck"}, {"text": "Datenbank erstellen", "correct": false, "because": "Strukturierung"}]');
